eval {MhExec dist +$exmh(folder) $m} -nowhatnowproc $args
MhAnnoSetup $exmh(folder) $m dist
} err] {
Exmh_Status "dist: $err" purple
return
}
}
Edit_Done send ;# Just send it
}
